-- Crafty Blossoms commerce platform. Server-mediated writes; amounts are INR paise.
begin;
create table if not exists public.admin_profiles(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
alter table public.admin_profiles add column if not exists role text not null default 'admin' check(role in('admin','manager','support'));
create table if not exists public.product_categories(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,parent_id uuid references public.product_categories(id),image jsonb,position integer not null default 0,published boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text not null,category text not null,price integer check(price>=0),stock integer not null default 0 check(stock>=0),published boolean not null default false,featured boolean not null default false,images jsonb not null default '[]',materials text,care text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.products add column if not exists category_id uuid references public.product_categories(id);
alter table public.products add column if not exists personalisation jsonb not null default '[]';
alter table public.products add column if not exists occasion_tags text[] not null default '{}';
alter table public.products add column if not exists recipient_tags text[] not null default '{}';
alter table public.products add column if not exists collections text[] not null default '{}';
alter table public.products add column if not exists production_days integer not null default 0 check(production_days between 0 and 180);
alter table public.products add column if not exists seo_title text;
alter table public.products add column if not exists seo_description text;
alter table public.products add column if not exists popularity integer not null default 0 check(popularity>=0);
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),sku text unique not null,name text not null,price integer not null check(price>=1),sale_price integer check(sale_price>=1 and sale_price<price),active boolean not null default false,created_at timestamptz not null default now());
create table public.inventory(variant_id uuid primary key references public.product_variants(id),on_hand integer not null default 0 check(on_hand>=0),reserved integer not null default 0 check(reserved>=0 and reserved<=on_hand),low_stock_threshold integer not null default 3 check(low_stock_threshold>=0),updated_at timestamptz not null default now());
create table public.customers(id uuid primary key references auth.users(id),name text not null default '',phone text not null default '',created_at timestamptz not null default now());
create table public.addresses(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,label text not null,details jsonb not null,created_at timestamptz not null default now());
create table public.wishlists(customer_id uuid not null references public.customers(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),primary key(customer_id,product_id));
create table public.carts(id uuid primary key default gen_random_uuid(),customer_id uuid unique references public.customers(id) on delete cascade,owner_key text unique not null,updated_at timestamptz not null default now());
create table public.cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts(id) on delete cascade,configuration_key text not null,variant_id uuid not null references public.product_variants(id),quantity integer not null check(quantity between 1 and 20),personalisation jsonb not null default '{}',unique(cart_id,configuration_key));
create table public.delivery_zones(id uuid primary key default gen_random_uuid(),name text not null,prefixes text[] not null check(cardinality(prefixes)>0),mode text not null check(mode in('standard','express')),fee integer not null check(fee>=0),min_days integer not null check(min_days>=0),max_days integer not null check(max_days>=min_days),scheduled boolean not null default false,active boolean not null default false);
create table public.coupons(id uuid primary key default gen_random_uuid(),code text unique not null check(code=upper(code)),kind text not null check(kind in('percent','fixed')),value integer not null check(value>0),minimum integer not null default 0 check(minimum>=0),maximum_discount integer check(maximum_discount>0),starts_at timestamptz not null default now(),expires_at timestamptz not null,max_uses integer not null check(max_uses>0),per_customer_limit integer not null default 1 check(per_customer_limit>0),active boolean not null default false,check(kind<>'percent' or value<=100),check(expires_at>starts_at));
create table public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid references public.customers(id),owner_key text not null,idempotency_key uuid unique not null,request_hash text not null,email text not null,address jsonb not null,recipient jsonb not null default '{}',gift_message text not null default '',delivery_instructions text not null default '',status text not null default 'awaiting_payment' check(status in('awaiting_payment','paid','in_production','shipped','delivered','expired','cancelled','payment_review','refunded')),subtotal integer not null check(subtotal>=0),discount integer not null check(discount>=0 and discount<=subtotal),shipping integer not null check(shipping>=0),tax integer not null check(tax>=0),total integer not null check(total=subtotal-discount+shipping+tax),currency text not null default 'INR' check(currency='INR'),coupon_id uuid references public.coupons(id),delivery_zone_id uuid not null references public.delivery_zones(id),estimated_date date not null,gateway_order_id text unique,payment_id text unique,gateway_state text not null default 'new' check(gateway_state in('new','creating','ready','uncertain')),expires_at timestamptz not null default now()+interval '20 minutes',restocked boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),product_id uuid not null references public.products(id),variant_id uuid not null references public.product_variants(id),name text not null,variant_name text not null,quantity integer not null check(quantity between 1 and 20),unit_price integer not null check(unit_price>0),personalisation jsonb not null default '{}');
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),provider_payment_id text unique not null,amount integer not null check(amount>0),currency text not null check(currency='INR'),status text not null check(status in('captured','partially_refunded','refunded')),refunded_amount integer not null default 0 check(refunded_amount>=0 and refunded_amount<=amount),created_at timestamptz not null default now());
create table public.coupon_redemptions(id uuid primary key default gen_random_uuid(),coupon_id uuid not null references public.coupons(id),order_id uuid unique not null references public.orders(id),owner_key text not null,status text not null check(status in('reserved','used','released')));
create table public.shipments(id uuid primary key default gen_random_uuid(),order_id uuid unique not null references public.orders(id),carrier text not null,tracking_number text not null,status text not null check(status in('ready','shipped','in_transit','delivered')),updated_at timestamptz not null default now());
create table public.inventory_history(id uuid primary key default gen_random_uuid(),variant_id uuid not null references public.product_variants(id),order_id uuid references public.orders(id),actor_id uuid references auth.users(id),delta integer not null,reason text not null,created_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id),product_id uuid not null references public.products(id),order_id uuid not null references public.orders(id),rating integer not null check(rating between 1 and 5),body text not null check(length(body) between 10 and 2000),display_name text not null,approved boolean not null default false,created_at timestamptz not null default now(),unique(customer_id,product_id,order_id));
create table public.support_requests(id uuid primary key default gen_random_uuid(),customer_id uuid references public.customers(id),order_id uuid not null references public.orders(id),kind text not null check(kind in('cancellation','return')),reason text not null,status text not null default 'new' check(status in('new','reviewing','approved','declined','completed')),notes text not null default '',created_at timestamptz not null default now());
create table public.refund_jobs(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),support_request_id uuid references public.support_requests(id),amount integer not null check(amount>0),reason text not null,status text not null default 'pending' check(status in('pending','processing','submitted','processed','uncertain','failed')),provider_refund_id text unique,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create unique index one_active_refund_per_order on public.refund_jobs(order_id) where status not in('failed');
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id text,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.app_settings(id boolean primary key default true check(id),settings jsonb not null default '{"commerce_enabled":false,"policies_approved":false,"tax_bps":0,"newsletter_enabled":false}');
insert into public.app_settings(id) values(true);
create table public.homepage_sections(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('hero','collection','new_arrivals','bestsellers','personalised','occasion','recipient','budget','bundle','reviews')),title text not null,description text not null default '',image jsonb,product_ids uuid[] not null default '{}',filter jsonb not null default '{}',href text not null default '/shop',position integer not null default 0,enabled boolean not null default false);
create table public.personalisation_uploads(id uuid primary key default gen_random_uuid(),owner_key text not null,customer_id uuid references public.customers(id),order_id uuid references public.orders(id),path text unique not null,content_type text not null,bytes integer not null check(bytes between 1 and 8388608),expires_at timestamptz not null default now()+interval '24 hours',created_at timestamptz not null default now());
create table public.webhook_events(event_id text primary key,kind text not null,order_id uuid references public.orders(id),created_at timestamptz not null default now());
create table public.email_outbox(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id),kind text not null,recipient text not null,payload jsonb not null default '{}',status text not null default 'pending' check(status in('pending','sending','sent','failed')),attempts integer not null default 0,lease_until timestamptz,provider_id text,created_at timestamptz not null default now(),unique(order_id,kind));
create table public.rate_limits(key text primary key,count integer not null,reset_at timestamptz not null);
create table if not exists public.custom_order_requests(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text not null,product_type text not null,colours text,measurements text,quantity integer not null check(quantity between 1 and 20),budget text,date_needed date,description text not null,lines jsonb,consent_at timestamptz not null,status text not null default 'New',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.newsletter_subscribers(id uuid primary key default gen_random_uuid(),email text unique not null,consent_at timestamptz not null,created_at timestamptz not null default now());
create index addresses_customer on public.addresses(customer_id);
create index variants_product on public.product_variants(product_id);
create index orders_customer on public.orders(customer_id,created_at desc);
create index orders_owner on public.orders(owner_key,created_at desc);
create index orders_expiry on public.orders(expires_at) where status='awaiting_payment';
create index order_items_order on public.order_items(order_id);
create index order_items_variant on public.order_items(variant_id);
create index payments_order on public.payments(order_id);
create index redemptions_coupon on public.coupon_redemptions(coupon_id,status,owner_key);
create index reviews_product on public.reviews(product_id) where approved;
create index support_order on public.support_requests(order_id);
create index inventory_history_variant on public.inventory_history(variant_id,created_at desc);
create index audit_created on public.audit_logs(created_at desc);
create index outbox_pending on public.email_outbox(status,lease_until);
create index uploads_owner on public.personalisation_uploads(owner_key);
-- All tables deny anonymous access. Customer read policies add defence in depth;
-- transactional writes can only happen in the server with a validated identity.
do $$ declare t text; begin foreach t in array array['admin_profiles','product_categories','products','product_variants','inventory','customers','addresses','wishlists','carts','cart_items','delivery_zones','coupons','orders','order_items','payments','coupon_redemptions','shipments','inventory_history','reviews','support_requests','refund_jobs','audit_logs','app_settings','homepage_sections','personalisation_uploads','webhook_events','email_outbox','rate_limits','custom_order_requests','newsletter_subscribers'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant select on public.customers,public.addresses,public.wishlists,public.orders,public.order_items,public.shipments,public.support_requests to authenticated;
create policy customer_self on public.customers for select to authenticated using(id=(select auth.uid()));
create policy addresses_self on public.addresses for select to authenticated using(customer_id=(select auth.uid()));
create policy wishlist_self on public.wishlists for select to authenticated using(customer_id=(select auth.uid()));
create policy orders_self on public.orders for select to authenticated using(customer_id=(select auth.uid()));
create policy order_items_self on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=(select auth.uid())));
create policy shipment_self on public.shipments for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=(select auth.uid())));
create policy support_self on public.support_requests for select to authenticated using(customer_id=(select auth.uid()));
create function public.cb_rate_limit(p_key text,p_limit integer,p_seconds integer) returns boolean language plpgsql security invoker set search_path=public,pg_temp as $$ declare n integer;begin insert into rate_limits(key,count,reset_at) values(p_key,1,now()+make_interval(secs=>p_seconds)) on conflict(key) do update set count=case when rate_limits.reset_at<now() then 1 else rate_limits.count+1 end,reset_at=case when rate_limits.reset_at<now() then now()+make_interval(secs=>p_seconds) else rate_limits.reset_at end returning count into n;return n<=p_limit;end $$;
create function public.cb_reserve_checkout(p_payload jsonb,p_customer_id uuid,p_owner text,p_hash text) returns orders language plpgsql security invoker set search_path=public,pg_temp as $$
declare o orders; z delivery_zones; c coupons; s jsonb; l jsonb; v record; f jsonb; val jsonb; q integer; fee integer; sub integer:=0; disc integer:=0; taxv integer; lead integer:=0; inv inventory; cid uuid; datev date; upload_id uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_payload->>'idempotencyKey',0));
 select * into o from orders where idempotency_key=(p_payload->>'idempotencyKey')::uuid;
 if found then if o.owner_key<>p_owner or o.request_hash<>p_hash then raise exception 'Checkout request does not match';end if;return o;end if;
 select settings into s from app_settings where id=true;
 if not coalesce((s->>'commerce_enabled')::boolean,false) or not coalesce((s->>'policies_approved')::boolean,false) then raise exception 'Online purchasing is not enabled';end if;
 select * into z from delivery_zones where id=(p_payload->>'delivery_zone_id')::uuid and active;
 if not found or not exists(select 1 from unnest(z.prefixes) as prefixes(prefix) where starts_with(p_payload->'address'->>'pincode',prefix)) then raise exception 'Delivery is not supported for this PIN code';end if;
 if jsonb_array_length(p_payload->'lines') not between 1 and 30 then raise exception 'Invalid shopping bag';end if;
 -- Lock every affected inventory row in one stable order, including repeated variants.
 perform 1 from inventory where variant_id in(select (value->>'variantId')::uuid from jsonb_array_elements(p_payload->'lines')) order by variant_id for update;
 for l in select value from jsonb_array_elements(p_payload->'lines') loop
  q=(l->>'quantity')::integer;if q not between 1 and 20 then raise exception 'Invalid quantity';end if;
  select pv.*,p.name as product_name,p.production_days,p.personalisation into v from product_variants pv join products p on p.id=pv.product_id where pv.id=(l->>'variantId')::uuid and pv.product_id=(l->>'productId')::uuid and pv.active and p.published for share of pv,p;
  if not found then raise exception 'A selected piece is unavailable';end if;
  select * into inv from inventory where variant_id=v.id;
  if not found or inv.on_hand-inv.reserved<q then raise exception 'Insufficient stock';end if;
  if exists(select 1 from jsonb_object_keys(l->'personalisation') k where not exists(select 1 from jsonb_array_elements(v.personalisation) x where x->>'key'=k)) then raise exception 'Unknown personalisation option';end if;
  fee=0;
  for f in select value from jsonb_array_elements(v.personalisation) loop
   val=l->'personalisation'->(f->>'key');
   if coalesce((f->>'required')::boolean,false) and (val is null or val='null'::jsonb or val='""'::jsonb or val='false'::jsonb) then raise exception 'A required personalisation field is missing';end if;
   if val is null or val='null'::jsonb or val='""'::jsonb or val='false'::jsonb then continue;end if;
   if f->>'type'='boolean' then if val<>'true'::jsonb then raise exception 'Invalid option';end if;
   else
    if jsonb_typeof(val)<>'string' or length(val#>>'{}')>coalesce((f->>'maxLength')::integer,500) then raise exception 'Invalid personalisation text';end if;
    if f->>'type'='select' and not (f->'options' @> jsonb_build_array(val)) then raise exception 'Invalid personalisation choice';end if;
    if f->>'type'='image' then upload_id=(val#>>'{}')::uuid; if not exists(select 1 from personalisation_uploads where id=upload_id and owner_key=p_owner and order_id is null and expires_at>now()) then raise exception 'Image upload expired or inaccessible';end if;end if;
   end if;
   fee=fee+coalesce((f->>'fee')::integer,0);if fee<0 then raise exception 'Invalid option fee';end if;
  end loop;
  sub=sub+(coalesce(v.sale_price,v.price)+fee)*q;lead=greatest(lead,v.production_days);
  update inventory set reserved=reserved+q,updated_at=now() where variant_id=v.id;
 end loop;
 if coalesce(p_payload->>'coupon','')<>'' then
  select * into c from coupons where code=upper(p_payload->>'coupon') for update;
  if not found or not c.active or c.starts_at>now() or c.expires_at<=now() or sub<c.minimum then raise exception 'Coupon is not valid for this bag';end if;
  if (select count(*) from coupon_redemptions where coupon_id=c.id and status in('reserved','used'))>=c.max_uses or (select count(*) from coupon_redemptions where coupon_id=c.id and owner_key=p_owner and status in('reserved','used'))>=c.per_customer_limit then raise exception 'Coupon usage limit reached';end if;
  disc=least(sub,case when c.kind='fixed' then c.value else floor(sub::numeric*c.value/100)::integer end,coalesce(c.maximum_discount,sub));cid=c.id;
 end if;
 datev=current_date+lead+z.max_days;
 if p_payload->>'delivery_date' is not null then if not z.scheduled or (p_payload->>'delivery_date')::date<datev or (p_payload->>'delivery_date')::date>current_date+180 then raise exception 'Requested delivery date is not supported';end if;datev=(p_payload->>'delivery_date')::date;end if;
 if coalesce((s->>'tax_bps')::integer,0) not between 0 and 10000 then raise exception 'Tax configuration is invalid';end if;
 taxv=round((sub-disc+z.fee)::numeric*coalesce((s->>'tax_bps')::integer,0)/10000)::integer;
 insert into orders(customer_id,owner_key,idempotency_key,request_hash,email,address,recipient,gift_message,delivery_instructions,subtotal,discount,shipping,tax,total,coupon_id,delivery_zone_id,estimated_date) values(p_customer_id,p_owner,(p_payload->>'idempotencyKey')::uuid,p_hash,p_payload->>'email',p_payload->'address',p_payload->'recipient',p_payload->>'gift_message',p_payload->>'delivery_instructions',sub,disc,z.fee,taxv,sub-disc+z.fee+taxv,cid,z.id,datev) returning * into o;
 if cid is not null then insert into coupon_redemptions(coupon_id,order_id,owner_key,status) values(cid,o.id,p_owner,'reserved');end if;
 for l in select value from jsonb_array_elements(p_payload->'lines') loop
  select pv.*,p.name as product_name,p.personalisation into v from product_variants pv join products p on p.id=pv.product_id where pv.id=(l->>'variantId')::uuid;
  fee=0;for f in select value from jsonb_array_elements(v.personalisation) loop val=l->'personalisation'->(f->>'key');if val is not null and val<>'null'::jsonb and val<>'""'::jsonb and val<>'false'::jsonb then fee=fee+coalesce((f->>'fee')::integer,0);if f->>'type'='image' then update personalisation_uploads set order_id=o.id where id=(val#>>'{}')::uuid and owner_key=p_owner;end if;end if;end loop;
  insert into order_items(order_id,product_id,variant_id,name,variant_name,quantity,unit_price,personalisation) values(o.id,v.product_id,v.id,v.product_name,v.name,(l->>'quantity')::integer,coalesce(v.sale_price,v.price)+fee,l->'personalisation');
 end loop;
 return o;
end $$;
create function public.cb_release_order(p_order uuid,p_reason text) returns boolean language plpgsql security invoker set search_path=public,pg_temp as $$ declare o orders;r record;begin select * into o from orders where id=p_order for update;if not found or o.status<>'awaiting_payment' then return false;end if;perform 1 from inventory where variant_id in(select variant_id from order_items where order_id=o.id) order by variant_id for update;for r in select variant_id,sum(quantity)::integer q from order_items where order_id=o.id group by variant_id loop update inventory set reserved=reserved-r.q,updated_at=now() where variant_id=r.variant_id;end loop;update orders set status=case when p_reason='expired' then 'expired' else 'cancelled' end,updated_at=now() where id=o.id;update coupon_redemptions set status='released' where order_id=o.id and status='reserved';return true;end $$;
create function public.cb_capture_payment(p_order uuid,p_gateway_order text,p_payment text,p_amount integer,p_currency text,p_event text) returns orders language plpgsql security invoker set search_path=public,pg_temp as $$ declare o orders;r record;begin
 select * into o from orders where id=p_order for update;if not found or o.gateway_order_id<>p_gateway_order or o.gateway_order_id is null or o.total<>p_amount or p_currency<>'INR' then raise exception 'Payment does not match the order';end if;
 if o.payment_id is not null and o.payment_id<>p_payment then raise exception 'Order already has a different payment';end if;
 insert into webhook_events(event_id,kind,order_id) values(p_event,'captured',o.id) on conflict do nothing;
 if not found then return o;end if;
 if o.payment_id=p_payment then return o;end if;
 insert into payments(order_id,provider_payment_id,amount,currency,status) values(o.id,p_payment,p_amount,p_currency,'captured');
 if o.status='awaiting_payment' then
 perform 1 from inventory where variant_id in(select variant_id from order_items where order_id=o.id) order by variant_id for update;
 for r in select variant_id,sum(quantity)::integer q from order_items where order_id=o.id group by variant_id loop update inventory set on_hand=on_hand-r.q,reserved=reserved-r.q,updated_at=now() where variant_id=r.variant_id;insert into inventory_history(variant_id,order_id,delta,reason) values(r.variant_id,o.id,-r.q,'Verified payment');end loop;
 update products set popularity=popularity+i.q from (select product_id,sum(quantity)::integer q from order_items where order_id=o.id group by product_id) i where products.id=i.product_id;update orders set status='paid',payment_id=p_payment,updated_at=now() where id=o.id returning * into o;update coupon_redemptions set status='used' where order_id=o.id;
 else update orders set status='payment_review',payment_id=p_payment,updated_at=now() where id=o.id returning * into o;end if;
 insert into email_outbox(order_id,kind,recipient,payload) values(o.id,case when o.status='paid' then 'payment_confirmed' else 'payment_review' end,o.email,jsonb_build_object('order_id',o.id,'total',o.total)) on conflict do nothing;
 return o;
end $$;
create function public.cb_adjust_stock(p_variant uuid,p_delta integer,p_reason text,p_actor uuid) returns inventory language plpgsql security invoker set search_path=public,pg_temp as $$ declare i inventory;begin if length(p_reason)<5 then raise exception 'Please give a stock adjustment reason';end if;select * into i from inventory where variant_id=p_variant for update;if not found or i.on_hand+p_delta<i.reserved then raise exception 'Stock cannot be below reserved quantity';end if;update inventory set on_hand=on_hand+p_delta,updated_at=now() where variant_id=p_variant returning * into i;insert into inventory_history(variant_id,actor_id,delta,reason) values(p_variant,p_actor,p_delta,p_reason);insert into audit_logs(actor_id,action,entity_type,entity_id) values(p_actor,'stock_adjustment','inventory',p_variant::text);return i;end $$;
create function public.cb_claim_email() returns setof email_outbox language plpgsql security invoker set search_path=public,pg_temp as $$ begin return query update email_outbox set status='sending',attempts=attempts+1,lease_until=now()+interval '5 minutes' where id in(select id from email_outbox where (status in('pending','failed') or (status='sending' and lease_until<now())) and attempts<8 order by created_at for update skip locked limit 10) returning *;end $$;
-- Restrict every transactional RPC to server-only execution.
do $$ declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'cb\_%' escape '\' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('brand-products','brand-products',true,8388608,array['image/jpeg','image/png','image/webp']),('order-personalisation','order-personalisation',false,8388608,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
-- No browser storage write policies. Server validates identity, provenance and file signatures.
commit;
-- Additional atomic transitions and database cart persistence.
create function public.cb_save_cart(p_owner text,p_customer uuid,p_lines jsonb) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare c uuid;l jsonb;begin if jsonb_array_length(p_lines)>30 then raise exception 'Too many bag items';end if;insert into carts(owner_key,customer_id) values(p_owner,p_customer) on conflict(owner_key) do update set updated_at=now() returning id into c;delete from cart_items where cart_id=c;for l in select value from jsonb_array_elements(p_lines) loop if not exists(select 1 from product_variants v join products p on p.id=v.product_id where v.id=(l->>'variantId')::uuid and p.id=(l->>'productId')::uuid and p.published) then raise exception 'A bag item is no longer available';end if;insert into cart_items(cart_id,configuration_key,variant_id,quantity,personalisation) values(c,l->>'key',(l->>'variantId')::uuid,(l->>'quantity')::integer,l->'personalisation');end loop;return c;end $$;
create function public.cb_fulfil(p_order uuid,p_status text,p_carrier text,p_tracking text,p_actor uuid) returns orders language plpgsql security invoker set search_path=public,pg_temp as $$ declare o orders;begin select * into o from orders where id=p_order for update;if not found or o.payment_id is null then raise exception 'Only verified paid orders can be fulfilled';end if;if not ((o.status='paid' and p_status in('in_production','shipped')) or (o.status='in_production' and p_status='shipped') or (o.status='shipped' and p_status='delivered')) then raise exception 'Invalid fulfilment transition';end if;if p_status='shipped' then if length(p_carrier)<2 or length(p_tracking)<2 then raise exception 'Carrier and tracking number are required';end if;insert into shipments(order_id,carrier,tracking_number,status) values(o.id,p_carrier,p_tracking,'shipped') on conflict(order_id) do update set carrier=excluded.carrier,tracking_number=excluded.tracking_number,status='shipped',updated_at=now();end if;if p_status='delivered' then update shipments set status='delivered',updated_at=now() where order_id=o.id;end if;update orders set status=p_status,updated_at=now() where id=o.id returning * into o;insert into audit_logs(actor_id,action,entity_type,entity_id) values(p_actor,p_status,'orders',o.id::text);insert into email_outbox(order_id,kind,recipient,payload) values(o.id,p_status,o.email,jsonb_build_object('order_id',o.id)) on conflict do nothing;return o;end $$;
create function public.cb_refund_confirmed(p_payment text,p_refunded integer,p_event text) returns boolean language plpgsql security invoker set search_path=public,pg_temp as $$ declare p payments;begin select * into p from payments where provider_payment_id=p_payment for update;if not found or p_refunded<0 or p_refunded>p.amount then raise exception 'Refund does not match a recorded payment';end if;insert into webhook_events(event_id,kind,order_id) values(p_event,'refunded',p.order_id) on conflict do nothing;if not found then return true;end if;update payments set refunded_amount=greatest(refunded_amount,p_refunded),status=case when greatest(refunded_amount,p_refunded)=amount then 'refunded' when p_refunded>0 then 'partially_refunded' else status end where id=p.id;if p_refunded=p.amount then update orders set status='refunded',updated_at=now() where id=p.order_id;end if;return true;end $$;
create function public.cb_restock_order(p_order uuid,p_actor uuid,p_reason text) returns boolean language plpgsql security invoker set search_path=public,pg_temp as $$ declare o orders;r record;begin select * into o from orders where id=p_order for update;if not found or o.status<>'refunded' or o.restocked then raise exception 'Only fully refunded, unrestocked orders can be restocked';end if;if length(p_reason)<5 then raise exception 'A return assessment reason is required';end if;perform 1 from inventory where variant_id in(select variant_id from order_items where order_id=o.id) order by variant_id for update;for r in select variant_id,sum(quantity)::integer q from order_items where order_id=o.id group by variant_id loop update inventory set on_hand=on_hand+r.q,updated_at=now() where variant_id=r.variant_id;insert into inventory_history(variant_id,order_id,actor_id,delta,reason) values(r.variant_id,o.id,p_actor,r.q,p_reason);end loop;update orders set restocked=true where id=o.id;insert into audit_logs(actor_id,action,entity_type,entity_id) values(p_actor,'restocked','orders',o.id::text);return true;end $$;
revoke all on function public.cb_save_cart(text,uuid,jsonb),public.cb_fulfil(uuid,text,text,text,uuid),public.cb_refund_confirmed(text,integer,text),public.cb_restock_order(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.cb_save_cart(text,uuid,jsonb),public.cb_fulfil(uuid,text,text,text,uuid),public.cb_refund_confirmed(text,integer,text),public.cb_restock_order(uuid,uuid,text) to service_role;
create function public.cb_dashboard() returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
select jsonb_build_object(
 'revenue',coalesce((select sum(amount-refunded_amount) from payments),0),
 'totalOrders',(select count(*) from orders where status not in('cancelled','expired')),
 'paidOrders',(select count(*) from orders where payment_id is not null),
 'pending',(select count(*) from orders where status='awaiting_payment'),
 'completed',(select count(*) from orders where status='delivered'),
 'average',coalesce((select round(sum(amount-refunded_amount)::numeric/nullif(count(distinct order_id),0)) from payments),0),
 'daily',coalesce((select jsonb_object_agg(sales_date,net) from(select to_char(created_at at time zone 'Asia/Kolkata','YYYY-MM-DD') as sales_date,sum(amount-refunded_amount) net from payments group by 1 order by 1 desc limit 30) d),'{}'::jsonb),
 'bestsellers',coalesce((select jsonb_object_agg(name,q) from(select i.name,sum(i.quantity) q from order_items i join orders o on o.id=i.order_id where o.status in('paid','in_production','shipped','delivered') group by i.name order by q desc limit 10) b),'{}'::jsonb),
 'lowStock',coalesce((select jsonb_agg(jsonb_build_object('on_hand',i.on_hand,'reserved',i.reserved,'product_variants',jsonb_build_object('name',v.name,'sku',v.sku))) from inventory i join product_variants v on v.id=i.variant_id where i.on_hand-i.reserved<=i.low_stock_threshold),'[]'::jsonb),
 'scope','All recorded orders and captured payments; latest 30 sales dates in India time'
) $$;
revoke all on function public.cb_dashboard() from public,anon,authenticated;
grant execute on function public.cb_dashboard() to service_role;
create function public.cb_enquiry_notification() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ declare target text;begin select settings->>'business_email' into target from app_settings where id=true;if coalesce(target,'')<>'' then insert into email_outbox(kind,recipient,payload) values('custom_enquiry',target,jsonb_build_object('request_id',new.id));end if;return new;end $$;
revoke all on function public.cb_enquiry_notification() from public,anon,authenticated;
create trigger enquiry_notification after insert on public.custom_order_requests for each row execute function public.cb_enquiry_notification();
alter table public.newsletter_subscribers add column if not exists subscribed boolean not null default true;
alter table public.newsletter_subscribers add column if not exists unsubscribed_at timestamptz;
create function public.cb_newsletter_notification() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ begin insert into email_outbox(kind,recipient,payload) values('newsletter_welcome',new.email,jsonb_build_object('subscriber_id',new.id));return new;end $$;
revoke all on function public.cb_newsletter_notification() from public,anon,authenticated;
create trigger newsletter_notification after insert on public.newsletter_subscribers for each row execute function public.cb_newsletter_notification();
